package com.harsh.explore.examples;import com.harsh.explore.data.Activities;import com.harsh.explore.data.Student;import com.harsh.explore.data.StudentDb;import java.util.List;import java.util.function.BiConsumer;import java.util.function.Consumer;import java.util.function.Predicate;public class PredicateAndConsumerExample {    /**     * This class demonstrates the use of Predicate and Consumer functional interfaces.     * It filters students based on their grade level and GPA, and then prints their names and activities.     */    static Predicate<Student> p1 = (student-> student.getGradeLevel()>= 4);    static Predicate<Student> p2 = (student-> student.getGpa()>= 3.9);    BiConsumer<String, List<String>> studentBiConsumer = (name, activities) -> {        System.out.println( name + ": " + activities);    };    Consumer<Student> StudentConsumer = (Student)->{        if(p1.and(p2).test(Student)){            studentBiConsumer.accept(Student.getName(), Student.getActivities());        }    };    /**     * This method prints the names and activities of students who meet the specified criteria.     * It uses a Predicate to filter students and a BiConsumer to print their details.     */    public void printNameAndActivities(List<Student> students) {        students.forEach(StudentConsumer);    }    public static void main(String[] args) {        List<Student> students = StudentDb.getAllStudents();        new PredicateAndConsumerExample().printNameAndActivities(students);    }}